suite = model.draft_tests(source)
for _ in range(max_rounds):
    survivors = [m for m in mutate(source)
                 if not any(t.fails_on(m) for t in suite)]
    if not survivors:
        break
    for m in survivors:
        test = model.write_test(source, target=m.diff)
        if test.passes_on(source):   # must agree with real code
            suite.append(test)       # and still needs a human on boundaries
